// Identidad y ciclo del movimiento.
//
// transaccion_id es DETERMINISTICO desde chat_id + message_id (DEC-005).
// Un reintento de n8n o un reenvio de Telegram produce el mismo id, y el
// nodo de idempotencia lo detecta antes de escribir.

const sobre = $('Entrada').first().json;
const c = sobre.contrato;
const ZONA = 'America/Bogota';

const cfg = {};
for (const f of $input.all().map(i => i.json)) {
  if (f && f.clave) cfg[String(f.clave).trim()] = String(f.valor ?? '').trim();
}

// ---------- resolverCiclo ----------
// Fronteras = dias del mes configurados. Un dia mayor al ultimo dia del
// mes se ajusta solo: asi 31 funciona en meses de 30 y en febrero
// (architecture.md §6.1, TC-23 a TC-26).
function fronterasDelMes(dt, dias) {
  const ultimo = dt.daysInMonth;
  const set = new Set(dias.map(d => Math.min(d, ultimo)));
  return [...set].sort((a, b) => a - b).map(d => dt.set({ day: d }).startOf('day'));
}

function resolverCiclo(fechaISO, diasInicio) {
  const f = DateTime.fromISO(fechaISO, { zone: ZONA }).startOf('day');
  const previo = f.minus({ months: 1 });
  const siguiente = f.plus({ months: 1 });

  const todas = [
    ...fronterasDelMes(previo, diasInicio),
    ...fronterasDelMes(f, diasInicio),
    ...fronterasDelMes(siguiente, diasInicio)
  ].sort((a, b) => a.toMillis() - b.toMillis());

  let inicio = null, fin = null;
  for (let i = 0; i < todas.length; i++) {
    if (todas[i] <= f && (i + 1 >= todas.length || todas[i + 1] > f)) {
      inicio = todas[i];
      fin = (i + 1 < todas.length) ? todas[i + 1].minus({ days: 1 }) : todas[i].endOf('month');
      break;
    }
  }
  if (!inicio) { inicio = todas[0]; fin = todas[1] ? todas[1].minus({ days: 1 }) : inicio.endOf('month'); }

  // Sufijo A/B/C segun el orden de la frontera dentro de su propio mes.
  const delMes = fronterasDelMes(inicio, diasInicio);
  const idx = delMes.findIndex(d => d.toISODate() === inicio.toISODate());
  const letra = String.fromCharCode(65 + (idx >= 0 ? idx : 0));

  return {
    ciclo_id: `${inicio.toFormat('yyyy-LL')}-${letra}`,
    inicio: inicio.toISODate(),
    fin: fin.toISODate()
  };
}

const diasInicio = (cfg.ciclo_dias_inicio || '1,16')
  .split(',').map(s => parseInt(s.trim(), 10)).filter(Number.isFinite);

const cicloMovimiento = resolverCiclo(c.fecha_movimiento, diasInicio);
const hoy = DateTime.now().setZone(ZONA).startOf('day');
const cicloVigente = resolverCiclo(hoy.toISODate(), diasInicio);

const cicloCerrado = cicloMovimiento.ciclo_id !== cicloVigente.ciclo_id;
const finVigente = DateTime.fromISO(cicloVigente.fin, { zone: ZONA });
const diasRestantes = Math.max(1, Math.floor(finVigente.diff(hoy, 'days').days) + 1);

// ---------- transaccion_id determinístico ----------
// require('crypto') esta bloqueado en el sandbox del Code node de esta
// instancia. No hace falta resistencia criptografica aca: solo que el
// mismo (chat_id, message_id) produzca siempre el mismo hash (idempotencia,
// DEC-005). FNV-1a de 32 bits alcanza de sobra para eso.
function fnv1a(str) {
  let h = 0x811c9dc5;
  for (let i = 0; i < str.length; i++) {
    h ^= str.charCodeAt(i);
    h = Math.imul(h, 0x01000193);
  }
  return (h >>> 0).toString(16).padStart(8, '0').toUpperCase();
}
const semilla = `${sobre.ctx.telegram_chat_id}:${sobre.ctx.telegram_message_id}`;
const hash6 = fnv1a(semilla).slice(0, 6);
const stamp = DateTime.fromISO(c.fecha_movimiento, { zone: ZONA }).toFormat('yyyyLLdd');
const transaccionId = `TX-${stamp}-${hash6}`;

return [{
  json: {
    ...sobre,
    config: cfg,
    calc: {
      transaccion_id: transaccionId,
      ciclo_movimiento: cicloMovimiento,
      ciclo_vigente: cicloVigente,
      ciclo_cerrado: cicloCerrado,
      dias_restantes: diasRestantes,
      hoy: hoy.toISODate()
    }
  }
}];

// Dos controles antes de escribir, en este orden:
//   1. Idempotencia: el transaccion_id ya existe -> no se escribe nada.
//   2. Duplicado por puntaje (architecture.md §12).

const s = $('Resolver Ciclo e ID').first().json;
const c = s.contrato;
const txs = $input.all().map(i => i.json).filter(t => t && t.transaccion_id);

// --- 1. Idempotencia (TC-42) ---
const yaExiste = txs.find(t => String(t.transaccion_id).trim() === s.calc.transaccion_id);
if (yaExiste) {
  return [{ json: { ...s, _ya_registrado: true, _duplicado_score: 0, _existente: yaExiste } }];
}

// --- 2. Puntaje de duplicado ---
const ZONA = 'America/Bogota';
const ventanaH = parseInt(s.config.tolerancia_duplicado_horas || '48', 10);
const ahora = DateTime.now().setZone(ZONA);

function norm(x) {
  return String(x || '').toLowerCase()
    .normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
}

let mejor = null;
let mejorPuntaje = 0;

for (const t of txs) {
  if (String(t.estado).trim() !== 'activo') continue;

  const reg = DateTime.fromISO(String(t.timestamp_registro || ''), { zone: ZONA });
  if (reg.isValid && ahora.diff(reg, 'hours').hours > ventanaH) continue;

  let p = 0;
  // Señales fuertes: por si solas confirman el duplicado.
  if (c.evidencia?.hash_archivo && norm(t.hash_archivo) === norm(c.evidencia.hash_archivo)) p += 100;
  if (String(t.telegram_message_id) === String(s.ctx.telegram_message_id)) p += 100;

  // Señales debiles: suman.
  if (Number(t.monto) === Number(c.monto)) p += 40;
  if (c.comercio_proveedor && norm(t.comercio_proveedor) === norm(c.comercio_proveedor)) p += 25;
  if (String(t.fecha_movimiento).trim() === c.fecha_movimiento) p += 20;
  if (String(t.categoria_id).trim() === c.categoria_id) p += 10;

  if (p > mejorPuntaje) { mejorPuntaje = p; mejor = t; }
}

return [{
  json: {
    ...s,
    _ya_registrado: false,
    _duplicado_score: mejorPuntaje,
    _duplicado_confirmado: mejorPuntaje >= 100,
    _duplicado_probable: mejorPuntaje >= 65 && mejorPuntaje < 100,
    _similar: mejor
  }
}];

// Aviso de duplicado. NO se escribe la transaccion (TC-18).
const s = $json;
const sim = s._similar || {};
const yaReg = s._ya_registrado;

const texto = yaReg
  ? `Este movimiento ya estaba registrado (${s.calc.transaccion_id}). No lo dupliqué.`
  : [
      '⚠️ Este gasto parece que ya está registrado.',
      '',
      `$${Number(sim.monto || 0).toLocaleString('es-CO')} — ${sim.comercio_proveedor || sim.categoria || 'sin proveedor'} — ${sim.fecha_movimiento || ''}`,
      '',
      '¿Lo registro de todas formas?'
    ].join('\n');

const teclado = yaReg ? null : {
  inline_keyboard: [[
    { text: 'Registrar igual', callback_data: `force:${s.calc.transaccion_id}` },
    { text: 'No, cancelar', callback_data: 'cancel' }
  ]]
};

return [{ json: { chat_id: s.ctx.telegram_chat_id, texto, teclado: teclado ? JSON.stringify(teclado) : null } }];

// Rama de error de escritura. Regla P6 de la arquitectura:
// si no se escribio, el usuario NO puede recibir un ✅ (TC-43).
const s = $('Idempotencia y Duplicados').first().json;
return [{
  json: {
    chat_id: s.ctx.telegram_chat_id,
    texto: '❌ No pude guardar el gasto. Nada quedó registrado. Volvé a enviarlo en un momento.',
    teclado: null,
    _fallo_escritura: true
  }
}];

// Recalcula el ciclo vigente completo desde Transacciones.
// No se hace un +=: se recalcula. Asi una anulacion, una correccion o
// una escritura perdida se corrigen solas en el siguiente movimiento.

const s = $('Idempotencia y Duplicados').first().json;
const fila = $('Construir Fila').first().json;
const categorias = $input.all().map(i => i.json).filter(c => c && c.categoria_id);

// Transacciones leidas antes de escribir + la recien escrita.
const previas = $('Leer Transacciones').all().map(i => i.json).filter(t => t && t.transaccion_id);
const todas = [...previas, fila];

const cicloVigente = s.calc.ciclo_vigente.ciclo_id;
const validas = todas.filter(t =>
  String(t.estado).trim() === 'activo' &&
  String(t.ciclo_id).trim() === cicloVigente
);

function netoDe(filtro) {
  let gasto = 0, reembolso = 0;
  for (const t of validas.filter(filtro)) {
    const m = Number(t.monto) || 0;
    if (t.tipo === 'gasto' || t.tipo === 'ajuste') gasto += m;
    else if (t.tipo === 'reembolso') reembolso += m;
    // ingreso y traslado quedan fuera del presupuesto (architecture.md §10)
  }
  return gasto - reembolso;
}

const umbral1 = parseFloat(s.config.umbral_aviso_1 || '70');
const umbral2 = parseFloat(s.config.umbral_aviso_2 || '85');
const umbralCrit = parseFloat(s.config.umbral_critico || '100');

let presupuestoTotal = 0;
let gastadoTotal = 0;
const filasCategorias = [];
let catDelMovimiento = null;
const alertas = [];

for (const c of categorias) {
  const activa = String(c.activa).toUpperCase() === 'TRUE';
  const presupuesto = Number(c.presupuesto) || 0;
  const gastado = netoDe(t => String(t.categoria_id).trim() === String(c.categoria_id).trim());

  if (activa) { presupuestoTotal += presupuesto; gastadoTotal += gastado; }

  const pct = presupuesto === 0 ? null : Math.round((gastado / presupuesto) * 1000) / 10;

  let estado = 'ok';
  if (presupuesto === 0) estado = 'sin_presupuesto';
  else if (pct > umbralCrit) estado = 'excedido';
  else if (pct >= umbralCrit) estado = 'limite';
  else if (pct >= umbral2) estado = 'alto';
  else if (pct >= umbral1) estado = 'aviso';

  filasCategorias.push({
    categoria_id: c.categoria_id,
    fecha_inicio: s.calc.ciclo_vigente.inicio,
    fecha_fin: s.calc.ciclo_vigente.fin,
    gastado,
    disponible: presupuesto - gastado,
    porcentaje_usado: pct === null ? '' : pct,
    estado
  });

  if (String(c.categoria_id).trim() === String(fila.categoria_id).trim()) {
    catDelMovimiento = { ...c, presupuesto, gastado, disponible: presupuesto - gastado, pct, estado };

    // Alertas de umbral, solo para la categoria tocada por este movimiento.
    if (presupuesto === 0) {
      alertas.push({ codigo: 'CATEGORIA_SIN_PRESUPUESTO', nivel: 'info', valor: 0, limite: 0 });
    } else {
      if (pct > umbralCrit) alertas.push({ codigo: 'CAT_EXCEDIDO', nivel: 'critico', valor: pct, limite: umbralCrit });
      else if (pct >= umbralCrit) alertas.push({ codigo: 'CAT_100', nivel: 'critico', valor: pct, limite: umbralCrit });
      if (pct >= umbral2 && pct <= umbralCrit) alertas.push({ codigo: 'CAT_85', nivel: 'alto', valor: pct, limite: umbral2 });
      if (pct >= umbral1 && pct < umbral2) alertas.push({ codigo: 'CAT_70', nivel: 'medio', valor: pct, limite: umbral1 });
    }
  }
}

const disponibleGlobal = presupuestoTotal - gastadoTotal;
const pctGlobal = presupuestoTotal === 0 ? 0 : Math.round((gastadoTotal / presupuestoTotal) * 1000) / 10;
const maximoDiario = Math.round(Math.max(disponibleGlobal, 0) / Math.max(s.calc.dias_restantes, 1));

if (pctGlobal >= umbralCrit) alertas.push({ codigo: 'GLOBAL_100', nivel: 'critico', valor: pctGlobal, limite: umbralCrit });
else if (pctGlobal >= umbral2) alertas.push({ codigo: 'GLOBAL_85', nivel: 'alto', valor: pctGlobal, limite: umbral2 });

return [{
  json: {
    ...s,
    fila,
    saldos: {
      categoria: catDelMovimiento,
      global: { presupuesto: presupuestoTotal, gastado: gastadoTotal, disponible: disponibleGlobal, porcentaje: pctGlobal },
      ciclo: s.calc.ciclo_vigente,
      dias_restantes: s.calc.dias_restantes,
      maximo_diario_sugerido: maximoDiario
    },
    filas_categorias: filasCategorias,
    alertas
  }
}];

// Anti-repeticion (DEC-011): clave ciclo_id|categoria_id|codigo.
// Si ya existe en este ciclo, la alerta no se vuelve a emitir. Al cambiar
// de ciclo la clave cambia y los umbrales pueden dispararse otra vez.

const s = $('Recalcular Saldos').first().json;
const existentes = new Set(
  $input.all().map(i => i.json)
    .filter(a => a && a.clave_dedupe)
    .map(a => String(a.clave_dedupe).trim())
);

const ciclo = s.saldos.ciclo.ciclo_id;
const catId = s.fila.categoria_id;
const catNombre = s.fila.categoria;
const ahora = DateTime.now().setZone('America/Bogota');
const stamp = ahora.toFormat('yyyyLLdd');

const PLANTILLAS = {
  CAT_70:  (n, d) => `🟡 Llevas el 70% del presupuesto de ${n}. Quedan $${d}.`,
  CAT_85:  (n, d) => `🟠 Estás cerca del límite de ${n}. Solo quedan $${d} en este ciclo.`,
  CAT_100: (n) => `🔴 Consumiste todo el presupuesto de ${n}.`,
  CAT_EXCEDIDO: (n, d, e) => `🚨 Excediste el presupuesto de ${n} en $${e}.`,
  GLOBAL_85: () => `🟠 Vas por el 85% del presupuesto total del ciclo.`,
  GLOBAL_100: () => `🚨 Consumiste el presupuesto total del ciclo.`,
  CATEGORIA_SIN_PRESUPUESTO: (n) => `ℹ️ ${n} no tiene presupuesto configurado. El gasto quedó registrado igual.`
};

const fmt = (v) => Math.abs(Math.round(v)).toLocaleString('es-CO');
const cat = s.saldos.categoria || {};
const nuevas = [];
let i = 0;

for (const a of s.alertas) {
  const esGlobal = a.codigo.startsWith('GLOBAL');
  const clave = `${ciclo}|${esGlobal ? 'GLOBAL' : catId}|${a.codigo}`;
  if (existentes.has(clave)) continue;

  const plantilla = PLANTILLAS[a.codigo];
  if (!plantilla) continue;
  const mensaje = plantilla(catNombre, fmt(cat.disponible || 0), fmt(Math.abs(cat.disponible || 0)));

  nuevas.push({
    alerta_id: `AL-${stamp}-${String(++i).padStart(3, '0')}${Math.random().toString(36).slice(2, 4).toUpperCase()}`,
    timestamp: ahora.toISO(),
    clave_dedupe: clave,
    tipo: a.codigo,
    nivel: a.nivel,
    categoria: esGlobal ? 'GLOBAL' : catNombre,
    valor_actual: a.valor,
    limite: a.limite,
    mensaje,
    enviada: 'TRUE',
    telegram_message_id: '',
    resuelta: 'FALSE',
    fecha_resolucion: ''
  });
}

if (nuevas.length === 0) return [{ json: { _sin_alertas: true } }];
return nuevas.map(json => ({ json }));

// Respuesta al usuario. Plantilla propia: nunca texto libre del modelo
// (security.md §6, control 5).

const s = $('Recalcular Saldos').first().json;
const cat = s.saldos.categoria;
const g = s.saldos.global;
const fmt = (v) => '$' + Math.round(Number(v) || 0).toLocaleString('es-CO');

const alertasNuevas = $input.all().map(i => i.json).filter(a => a && a.mensaje);

const esReembolso = s.fila.tipo === 'reembolso';
const titulo = esReembolso
  ? `✅ Reembolso registrado: ${fmt(s.fila.monto)} en ${s.fila.categoria}`
  : `✅ Gasto registrado: ${fmt(s.fila.monto)} en ${s.fila.categoria}`;

const lineas = [titulo, ''];

if (cat && cat.presupuesto > 0) {
  lineas.push(
    `${cat.nombre}`,
    `• Presupuesto: ${fmt(cat.presupuesto)}`,
    `• Gastado: ${fmt(cat.gastado)}`,
    `• Disponible: ${fmt(cat.disponible)}`,
    `• Usado: ${cat.pct}%`,
    ''
  );
} else if (cat) {
  lineas.push(`${cat.nombre} no tiene presupuesto configurado.`, '');
}

lineas.push(
  'Estado general',
  `• Disponible: ${fmt(g.disponible)}`,
  `• Faltan ${s.saldos.dias_restantes} días para el próximo ingreso`,
  `• Máximo diario sugerido: ${fmt(s.saldos.maximo_diario_sugerido)}`
);

if (s.calc.ciclo_cerrado) {
  lineas.push('', `ℹ️ Se registró en el ciclo ${s.calc.ciclo_movimiento.ciclo_id}, que ya está cerrado. No afecta el ciclo actual.`);
}

for (const a of alertasNuevas) lineas.push('', a.mensaje);

// El maximo diario es aritmetica, no consejo financiero (architecture.md §10).
lineas.push('', '_Referencia matemática, no recomendación financiera._');

return [{ json: { chat_id: s.ctx.telegram_chat_id, texto: lineas.join('\n'), teclado: null } }];

// Un evento de Auditoria por cada escritura en Transacciones
// (regla de integridad #7 del data-model).
const s = $('Recalcular Saldos').first().json;
const ahora = DateTime.now().setZone('America/Bogota');
const stamp = ahora.toFormat('yyyyLLdd');
const rnd = Math.random().toString(36).slice(2, 6).toUpperCase();

return [{
  json: {
    evento_id: `EV-${stamp}-${rnd}`,
    timestamp: ahora.toISO(),
    correlation_id: s.meta.correlation_id,
    workflow: '04-registrar-movimiento',
    ejecucion: String(s.meta.execution_id || ''),
    usuario: String(s.ctx.telegram_user_id ?? ''),
    accion: 'escribir_transaccion',
    resultado: 'ok',
    detalle: `${s.calc.transaccion_id} registrada en ${s.fila.categoria}`,
    error: '',
    datos_tecnicos: JSON.stringify({
      via: s._via || 'desconocida',
      confianza: s.contrato.confianza,
      duplicado_score: s._duplicado_score,
      ciclo: s.saldos.ciclo.ciclo_id,
      alertas: s.alertas.map(a => a.codigo)
    })
  }
}];

// Arma la fila en el orden EXACTO de columnas de 'Transacciones'.
const HEADERS = ["transaccion_id", "timestamp_registro", "fecha_movimiento", "ciclo_id", "tipo", "monto", "moneda", "categoria_id", "categoria", "subcategoria", "descripcion", "comercio_proveedor", "metodo_pago", "persona", "origen", "telegram_user_id", "telegram_chat_id", "telegram_message_id", "file_id", "archivo_url_o_referencia", "hash_archivo", "texto_original", "datos_extraidos", "confianza_ia", "requiere_revision", "estado", "posible_duplicado", "transaccion_relacionada", "correlation_id", "notas"];
const item = $json;
const fila = HEADERS.map(h => item[h] !== undefined && item[h] !== null ? item[h] : '');
return { json: { fila } };

// Busca la fila por 'categoria_id' en 'Categorias', fusiona los campos
// nuevos sobre la fila existente y arma el rango a actualizar.
const HEADERS = ["categoria_id", "nombre", "descripcion", "grupo", "presupuesto", "ciclo", "fecha_inicio", "fecha_fin", "gastado", "disponible", "porcentaje_usado", "estado", "activa", "palabras_clave", "notas"];
const MATCH_COL = 'categoria_id';
const filas = $('Leer Categorias').all().map(i => i.json);
const nuevo = $json;
const idx = filas.findIndex(f => String(f[MATCH_COL]).trim() === String(nuevo[MATCH_COL]).trim());
if (idx === -1) { return { json: { _sin_fila: true } }; }
const filaSheets = idx + 2;
const fusionada = { ...filas[idx], ...nuevo };
const valores = HEADERS.map(h => fusionada[h] !== undefined && fusionada[h] !== null ? fusionada[h] : '');
return { json: { fila_sheets: filaSheets, valores } };

// Arma la fila en el orden EXACTO de columnas de 'Alertas'.
const HEADERS = ["alerta_id", "timestamp", "clave_dedupe", "tipo", "nivel", "categoria", "valor_actual", "limite", "mensaje", "enviada", "telegram_message_id", "resuelta", "fecha_resolucion"];
const item = $json;
const fila = HEADERS.map(h => item[h] !== undefined && item[h] !== null ? item[h] : '');
return { json: { fila } };

// Arma la fila en el orden EXACTO de columnas de 'Auditoria'.
const HEADERS = ["evento_id", "timestamp", "correlation_id", "workflow", "ejecucion", "usuario", "accion", "resultado", "detalle", "error", "datos_tecnicos"];
const item = $json;
const fila = HEADERS.map(h => item[h] !== undefined && item[h] !== null ? item[h] : '');
return { json: { fila } };

// Traduce el formato {inline_keyboard:[[{text,callback_data}]]}
// (el que arman los Code nodes previos) al formato que espera
// el nodo nativo Telegram: rows[].row.buttons[].additionalFields.
const s = $json;
let filas = [];
if (s.teclado) {
  let ik;
  try { ik = JSON.parse(s.teclado).inline_keyboard; } catch (e) { ik = []; }
  filas = ik.map(fila => ({ row: { buttons: fila.map(b => ({ text: b.text, additionalFields: { callback_data: b.callback_data } })) } }));
}
return [{ json: { ...s, _filas_botones: filas, _con_botones: filas.length > 0 } }];
